select t1.* from(SELECT p.finance_amount, p.tenant_id, p.project_id, ( SELECT count(*) FROM con_contract_cashflow t, con_contract tt WHERE tt.project_id = p.project_id AND t.contract_id = tt.CONTRACT_ID AND tt.contract_status in('INCEPT','PENDING') AND nvl(t.WRITE_OFF_FLAG, 'NOT') = 'FULL' AND T.cf_item IN ( 1, 3 ) AND T.cf_status != 'BLOCK' ) RECEIVED_TIMES, /* ( SELECT sum(t.lease_times) FROM con_contract t WHERE t.project_id = p.project_id AND t.contract_status = 'INCEPT' ) total_times,*/ (select sum(pq.LEASE_TERM) from con_contract ct ,prj_project pp,prj_quotation pq where ct.project_id=pp.PROJECT_ID and ct.QUOTATION_ID=pq.QUOTATION_ID and ct.contract_status in('INCEPT','PENDING') and pp.project_id=p.project_id) AS total_times, /*(select pq.LEASE_TERM from prj_quotation pq where pq.SOURCE_DOCUMENT_ID=p.project_id and pq.DATA_CLASS='VIRTUAL_CON' and pq.SOURCE_DOCUMENT_CATEGORY='PRJ_PROJECT') AS total_times,*/ ( SELECT nvl( sum( t.DUE_AMOUNT - nvl(t.RECEIVED_AMOUNT, 0) ), 0 ) FROM con_contract_cashflow t, con_contract tt WHERE tt.project_id = p.project_id AND t.contract_id = tt.CONTRACT_ID AND tt.contract_status in('INCEPT','PENDING') AND t.DUE_date < sysdate AND nvl(t.WRITE_OFF_FLAG, 'NOT') != 'FULL' ) OVERDUE_AMOUNT, ( SELECT count(*) FROM con_contract_cashflow t, con_contract tt WHERE tt.project_id = p.project_id AND t.contract_id = tt.CONTRACT_ID AND tt.contract_status in('INCEPT','PENDING') AND t.DUE_date < sysdate AND nvl(t.WRITE_OFF_FLAG, 'NOT') != 'FULL' ) OVERDUE_TIMES, ( SELECT nvl(SUM(TO_NUMBER( sysdate - t.due_date )), 0) FROM con_contract_cashflow t, con_contract tt WHERE tt.project_id = p.project_id AND t.contract_id = tt.CONTRACT_ID AND tt.contract_status in('INCEPT','PENDING') AND t.DUE_date < sysdate AND nvl(t.WRITE_OFF_FLAG, 'NOT') != 'FULL' ) OVERDUE_DAYS, CASE WHEN (select afe.FINAL_ASSETS_CLASS_RESULT from ast_fc_estimate afe where afe.CONTRACT_NUMBER = (SELECT pp.contract_number FROM prj_project pp WHERE pp.project_id = p.project_id) and rownum=1 ) != '' THEN ( SELECT v.meaning FROM sys_code_value_b_v v WHERE v.code = 'ASSET_CLASSIFICATION_RESULTS' AND (select afe.FINAL_ASSETS_CLASS_RESULT from ast_fc_estimate afe where afe.CONTRACT_NUMBER = (SELECT pp.contract_number FROM prj_project pp WHERE pp.project_id = p.project_id) and rownum=1 ) = v.CODE_VALUE ) ELSE ( SELECT v.meaning FROM sys_code_value_b_v v WHERE v.code = 'ASSET_CLASSIFICATION_RESULTS' AND (select afer.FIVE_CLASS_CODE_BY_SYSTEM from ast_fc_estimate_result afer where afer.FC_ESTIMATE_ID = (select afe.FC_ESTIMATE_ID from ast_fc_estimate afe where afe.CONTRACT_NUMBER = (SELECT pp.contract_number FROM prj_project pp WHERE pp.project_id = p.project_id) and rownum=1 )) = v.CODE_VALUE )
END FIVE_CLASS_RESULT FROM prj_project p WHERE p.DATA_CLASS = 'VIRTUAL_CON' AND p.data_type = 'NORMAL' AND p.contract_status = 'SIGN' AND p.project_id IN ( SELECT c.project_id FROM con_contract c WHERE c.data_class = 'NORMAL' AND c.contract_status in('INCEPT','PENDING') ))t1
and t1.tenant_id = #{bpId}

SELECT p.*, ( SELECT pp.contract_name FROM prj_project pp WHERE pp.project_id = p.project_id ) contract_name, ( SELECT pp.contract_number FROM prj_project pp WHERE pp.project_id = p.project_id ) contract_number, ( SELECT pp.contract_num FROM prj_project pp WHERE pp.project_id = p.project_id ) contract_num, ( SELECT pp.finance_amount FROM prj_project pp WHERE pp.project_id = p.project_id ) finance_amount FROM plm_risk_warning_info p
1=1
and P.risk_warning_id = #{riskWarningId}

